template <
    class T,  // The type of elements stored
    class Alloc = std::allocator<T>  // The memory allocator, which handles dynamic memory allocation
> class std::vector {
    public:
        // Key members (implementation notes):
        // - T* begin_;  // Pointer to the start of the array (contiguous memory)
        // - T* end_;    // Pointer to one past the last element (current size)
        // - T* capacity_end_;  // Pointer to one past the allocated memory (reserved capacity)

        void push_back(const T& value);  // Adds an element; may trigger reallocation if size == capacity
        size_t size() const;  // Returns the number of elements (runtime check)
        size_t capacity() const;  // Returns the allocated capacity (runtime check)
        // Note: Compilers may inline these for performance, but reallocation involves runtime heap operations.
};
